# -*- coding: utf-8 -*-
# Merzlyak 10, proof tasks 50–74. Identities re-derived; 22.13(2) question restored from OCR (first term is a fraction).
P = {'G10_TB_§21_21_9_3': {'k': '$\\sin(45^{\\circ} + \\alpha) - \\cos(45^{\\circ} + \\alpha) = \\dfrac{\\sqrt{2}}{2}(\\cos\\alpha + \\sin\\alpha) - \\dfrac{\\sqrt{2}}{2}(\\cos\\alpha - \\sin\\alpha) = \\sqrt{2}\\sin\\alpha$, а знаменатель аналогично равен $\\sqrt{2}\\cos\\alpha$, поэтому дробь равна $\\operatorname{tg}\\alpha$.', 'd': [('Числитель равен $\\sqrt{2}\\cos\\alpha$, знаменатель $\\sqrt{2}\\sin\\alpha$, поэтому дробь равна $\\operatorname{ctg}\\alpha$, поэтому тождество неверно.', '$\\cos(45^{\\circ} + \\alpha) = \\dfrac{\\sqrt{2}}{2}(\\cos\\alpha - \\sin\\alpha)$; в числителе остаётся $\\sqrt{2}\\sin\\alpha$.'), ('Разделив числитель и знаменатель на $\\cos(45^{\\circ} + \\alpha)$, получаем $\\dfrac{\\operatorname{tg}(45^{\\circ} + \\alpha) - 1}{\\operatorname{tg}(45^{\\circ} + \\alpha) + 1} = \\operatorname{tg}(45^{\\circ} + \\alpha)$, поэтому тождество неверно.', '$\\dfrac{\\operatorname{tg} x - 1}{\\operatorname{tg} x + 1} = \\operatorname{tg}(x - 45^{\\circ})$, и при $x = 45^{\\circ} + \\alpha$ это $\\operatorname{tg}\\alpha$.'), ('$\\sin(45^{\\circ} + \\alpha) = \\sin 45^{\\circ} + \\sin\\alpha$ и $\\cos(45^{\\circ} + \\alpha) = \\cos 45^{\\circ} + \\cos\\alpha$, поэтому дробь равна $\\dfrac{\\sin\\alpha - \\cos\\alpha}{\\sqrt{2} + \\sin\\alpha + \\cos\\alpha}$, поэтому тождество неверно.', 'Синус и косинус суммы не равны сумме синусов и косинусов.')]}, 'G10_TB_§21_21_9_4': {'k': 'Числитель $\\sin\\alpha + 2\\left(\\dfrac{\\sqrt{3}}{2}\\cos\\alpha - \\dfrac{1}{2}\\sin\\alpha\\right) = \\sqrt{3}\\cos\\alpha$, знаменатель $2\\left(\\dfrac{\\sqrt{3}}{2}\\cos\\alpha + \\dfrac{1}{2}\\sin\\alpha\\right) - \\sqrt{3}\\cos\\alpha = \\sin\\alpha$, поэтому дробь равна $\\sqrt{3}\\operatorname{ctg}\\alpha$.', 'd': [('Числитель равен $\\sqrt{3}\\sin\\alpha$, знаменатель $\\cos\\alpha$, поэтому дробь равна $\\sqrt{3}\\operatorname{tg}\\alpha$, поэтому тождество неверно.', '$\\sin(60^{\\circ} - \\alpha) = \\dfrac{\\sqrt{3}}{2}\\cos\\alpha - \\dfrac{1}{2}\\sin\\alpha$, поэтому числитель равен $\\sqrt{3}\\cos\\alpha$.'), ('Числитель $\\sin\\alpha + 2\\left(\\dfrac{1}{2}\\cos\\alpha - \\dfrac{\\sqrt{3}}{2}\\sin\\alpha\\right)$ не упрощается до $\\sqrt{3}\\cos\\alpha$, поэтому тождество неверно.', '$\\sin 60^{\\circ} = \\dfrac{\\sqrt{3}}{2}$, $\\cos 60^{\\circ} = \\dfrac{1}{2}$: значения перепутаны.'), ('Числитель равен $\\sqrt{3}\\cos\\alpha$, знаменатель $2\\cos(30^{\\circ} - \\alpha) - \\sqrt{3}\\cos\\alpha = 2\\cos 30^{\\circ} - 2\\cos\\alpha - \\sqrt{3}\\cos\\alpha$, поэтому дробь не равна $\\sqrt{3}\\operatorname{ctg}\\alpha$.', 'Косинус разности не равен разности косинусов: $\\cos(30^{\\circ} - \\alpha) = \\dfrac{\\sqrt{3}}{2}\\cos\\alpha + \\dfrac{1}{2}\\sin\\alpha$.')]}, 'G10_TB_§22_22_10_1': {'k': 'По формулам приведения $\\sin(\\pi - \\alpha) = \\sin\\alpha$, $\\sin(\\alpha + 2\\pi) = \\sin\\alpha$, $\\operatorname{tg}(\\pi + \\alpha) = \\operatorname{tg}\\alpha$, $\\cos\\left(\\dfrac{\\pi}{2} + \\alpha\\right) = -\\sin\\alpha$, поэтому левая часть равна $\\dfrac{\\sin^{2}\\alpha}{-\\operatorname{tg}\\alpha\\sin\\alpha} = -\\dfrac{\\sin\\alpha}{\\operatorname{tg}\\alpha} = -\\cos\\alpha$.', 'd': [('По формулам приведения $\\cos\\left(\\dfrac{\\pi}{2} + \\alpha\\right) = \\sin\\alpha$, поэтому левая часть равна $\\dfrac{\\sin^{2}\\alpha}{\\operatorname{tg}\\alpha\\sin\\alpha} = \\cos\\alpha$, поэтому тождество неверно.', '$\\cos\\left(\\dfrac{\\pi}{2} + \\alpha\\right) = -\\sin\\alpha$: во второй четверти косинус отрицателен.'), ('По формулам приведения $\\operatorname{tg}(\\pi + \\alpha) = -\\operatorname{tg}\\alpha$, поэтому левая часть равна $\\dfrac{\\sin^{2}\\alpha}{\\operatorname{tg}\\alpha\\sin\\alpha} = \\cos\\alpha$, поэтому тождество неверно.', 'Период тангенса — $\\pi$, поэтому $\\operatorname{tg}(\\pi + \\alpha) = \\operatorname{tg}\\alpha$.'), ('По формулам приведения $\\sin(\\pi - \\alpha) = -\\sin\\alpha$, поэтому левая часть равна $\\dfrac{-\\sin^{2}\\alpha}{-\\operatorname{tg}\\alpha\\sin\\alpha} = \\cos\\alpha$, поэтому тождество неверно.', '$\\sin(\\pi - \\alpha) = \\sin\\alpha$: во второй четверти синус положителен.')]}, 'G10_TB_§22_22_10_2': {'k': 'По формулам приведения $\\sin(\\pi + x)\\cos\\left(\\dfrac{\\pi}{2} - x\\right) = -\\sin x \\cdot \\sin x$ и $\\cos(2\\pi + x)\\sin\\left(\\dfrac{3\\pi}{2} + x\\right) = \\cos x \\cdot (-\\cos x)$, поэтому левая часть равна $-(\\sin^{2} x + \\cos^{2} x) = -1$.', 'd': [('$\\sin(\\pi + x) = \\sin x$, поэтому левая часть равна $\\sin^{2} x - \\cos^{2} x$, поэтому тождество неверно.', '$\\sin(\\pi + x) = -\\sin x$: в третьей четверти синус отрицателен.'), ('$\\sin\\left(\\dfrac{3\\pi}{2} + x\\right) = \\cos x$, поэтому левая часть равна $-\\sin^{2} x + \\cos^{2} x = \\cos 2x$, поэтому тождество неверно.', '$\\sin\\left(\\dfrac{3\\pi}{2} + x\\right) = -\\cos x$: в четвёртой четверти синус отрицателен.'), ('$\\cos\\left(\\dfrac{\\pi}{2} - x\\right) = \\cos x$, поэтому левая часть равна $-\\sin x\\cos x - \\cos^{2} x$, поэтому тождество неверно.', 'При $\\dfrac{\\pi}{2}$ функция меняется на кофункцию: $\\cos\\left(\\dfrac{\\pi}{2} - x\\right) = \\sin x$.')]}, 'G10_TB_§23_22_13_1': {'k': '$\\operatorname{tg}\\dfrac{5\\pi}{4} = 1$, $\\operatorname{tg}\\left(\\dfrac{\\pi}{2} - \\alpha\\right) = \\operatorname{ctg}\\alpha$, $\\operatorname{ctg}\\dfrac{9\\pi}{4} = 1$, $\\operatorname{ctg}(\\pi - \\alpha) = -\\operatorname{ctg}\\alpha$, поэтому левая часть равна $(1 + \\operatorname{ctg}\\alpha)^{2} + (1 - \\operatorname{ctg}\\alpha)^{2} = 2 + 2\\operatorname{ctg}^{2}\\alpha = \\dfrac{2}{\\sin^{2}\\alpha}$.', 'd': [('$\\operatorname{tg}\\left(\\dfrac{\\pi}{2} - \\alpha\\right) = \\operatorname{tg}\\alpha$ и $\\operatorname{ctg}(\\pi - \\alpha) = -\\operatorname{tg}\\alpha$, поэтому левая часть равна $2 + 2\\operatorname{tg}^{2}\\alpha = \\dfrac{2}{\\cos^{2}\\alpha}$, поэтому тождество неверно.', 'При $\\dfrac{\\pi}{2}$ тангенс меняется на котангенс, а при $\\pi$ функция не меняется: $\\operatorname{ctg}(\\pi - \\alpha) = -\\operatorname{ctg}\\alpha$.'), ('$\\operatorname{tg}\\dfrac{5\\pi}{4} = -1$, поэтому левая часть равна $(\\operatorname{ctg}\\alpha - 1)^{2} + (1 - \\operatorname{ctg}\\alpha)^{2} = 2(1 - \\operatorname{ctg}\\alpha)^{2}$, поэтому тождество неверно.', '$\\operatorname{tg}\\dfrac{5\\pi}{4} = \\operatorname{tg}\\dfrac{\\pi}{4} = 1$: период тангенса — $\\pi$.'), ('Левая часть равна $(1 + \\operatorname{ctg}\\alpha)^{2} + (1 - \\operatorname{ctg}\\alpha)^{2} = 2\\operatorname{ctg}^{2}\\alpha$, поэтому тождество неверно.', 'При раскрытии скобок остаётся $1 + 1 = 2$: сумма равна $2 + 2\\operatorname{ctg}^{2}\\alpha$.')]}, 'G10_TB_§23_22_13_2': {'q': 'Докажите тождество: $\\dfrac{\\cos^{2}\\left(\\dfrac{\\pi}{3} + \\alpha\\right)}{\\operatorname{tg}^{2}\\left(\\dfrac{\\pi}{6} - \\alpha\\right)} + \\sin^{2}\\left(\\dfrac{\\pi}{3} + \\alpha\\right) \\cdot \\operatorname{tg}^{2}\\left(\\dfrac{\\pi}{6} - \\alpha\\right) = 1$', 'qwhy': 'первое слагаемое — дробь (в условии было произведение, и тождество было неверным); формулировка сверена с текстом учебника', 'k': 'При $x = \\dfrac{\\pi}{3} + \\alpha$ имеем $\\dfrac{\\pi}{6} - \\alpha = \\dfrac{\\pi}{2} - x$, т. е. $\\operatorname{tg}\\left(\\dfrac{\\pi}{6} - \\alpha\\right) = \\operatorname{ctg} x$, поэтому левая часть равна $\\dfrac{\\cos^{2} x}{\\operatorname{ctg}^{2} x} + \\sin^{2} x \\operatorname{ctg}^{2} x = \\sin^{2} x + \\cos^{2} x = 1$.', 'd': [('При $x = \\dfrac{\\pi}{3} + \\alpha$ имеем $\\operatorname{tg}\\left(\\dfrac{\\pi}{6} - \\alpha\\right) = \\operatorname{tg} x$, поэтому левая часть равна $\\dfrac{\\cos^{4} x}{\\sin^{2} x} + \\dfrac{\\sin^{4} x}{\\cos^{2} x}$, поэтому тождество неверно.', '$\\dfrac{\\pi}{6} - \\alpha = \\dfrac{\\pi}{2} - x$, поэтому $\\operatorname{tg}\\left(\\dfrac{\\pi}{6} - \\alpha\\right) = \\operatorname{ctg} x$.'), ('При $x = \\dfrac{\\pi}{3} + \\alpha$ левая часть равна $\\dfrac{\\cos^{2} x}{\\operatorname{ctg}^{2} x} + \\sin^{2} x\\operatorname{ctg}^{2} x = \\cos^{2} x \\operatorname{tg}^{2} x + \\sin^{2} x\\operatorname{ctg}^{2} x = 2$.', '$\\cos^{2} x\\operatorname{tg}^{2} x = \\sin^{2} x$ и $\\sin^{2} x\\operatorname{ctg}^{2} x = \\cos^{2} x$, их сумма равна $1$, а не $2$.'), ('При $x = \\dfrac{\\pi}{3} + \\alpha$ имеем $\\operatorname{tg}\\left(\\dfrac{\\pi}{6} - \\alpha\\right) = -\\operatorname{ctg} x$, поэтому левая часть равна $-\\sin^{2} x - \\cos^{2} x = -1$, поэтому тождество неверно.', 'Квадрат не зависит от знака: $\\operatorname{tg}^{2}\\left(\\dfrac{\\pi}{6} - \\alpha\\right) = \\operatorname{ctg}^{2} x$, к тому же $\\operatorname{tg}\\left(\\dfrac{\\pi}{2} - x\\right) = \\operatorname{ctg} x$ без знака «−».')]}, 'G10_TB_§23_22_13_3': {'k': '$\\cos^{4}(\\alpha - \\pi) = \\cos^{4}\\alpha$, $\\cos^{4}\\left(\\alpha - \\dfrac{3\\pi}{2}\\right) = \\sin^{4}\\alpha$, $\\sin^{4}\\left(\\alpha + \\dfrac{3\\pi}{2}\\right) = \\cos^{4}\\alpha$, а $\\sin^{4}\\alpha + \\cos^{4}\\alpha - 1 = -2\\sin^{2}\\alpha\\cos^{2}\\alpha$, поэтому левая часть равна $\\dfrac{\\cos^{4}\\alpha}{-2\\sin^{2}\\alpha\\cos^{2}\\alpha} = -\\dfrac{1}{2}\\operatorname{ctg}^{2}\\alpha$.', 'd': [('$\\sin^{4}\\alpha + \\cos^{4}\\alpha - 1 = 2\\sin^{2}\\alpha\\cos^{2}\\alpha$, поэтому левая часть равна $\\dfrac{1}{2}\\operatorname{ctg}^{2}\\alpha$, поэтому тождество неверно.', '$\\sin^{4}\\alpha + \\cos^{4}\\alpha = (\\sin^{2}\\alpha + \\cos^{2}\\alpha)^{2} - 2\\sin^{2}\\alpha\\cos^{2}\\alpha = 1 - 2\\sin^{2}\\alpha\\cos^{2}\\alpha$.'), ('$\\cos^{4}\\left(\\alpha - \\dfrac{3\\pi}{2}\\right) = \\cos^{4}\\alpha$ и $\\sin^{4}\\left(\\alpha + \\dfrac{3\\pi}{2}\\right) = \\sin^{4}\\alpha$, поэтому знаменатель равен $-2\\sin^{2}\\alpha\\cos^{2}\\alpha$ и левая часть равна $-\\dfrac{1}{2}\\operatorname{ctg}^{2}\\alpha$.', 'При $\\dfrac{3\\pi}{2}$ функция меняется на кофункцию; ответ совпал лишь потому, что $\\sin^{4} + \\cos^{4}$ симметрично, но формулы приведения применены неверно.'), ('$\\cos^{4}(\\alpha - \\pi) = -\\cos^{4}\\alpha$, поэтому левая часть равна $\\dfrac{1}{2}\\operatorname{ctg}^{2}\\alpha$, поэтому тождество неверно.', 'Чётная степень неотрицательна: $\\cos^{4}(\\alpha - \\pi) = (-\\cos\\alpha)^{4} = \\cos^{4}\\alpha$.')]}, 'G10_TB_§23_23_35_1': {'k': 'Умножим и разделим на $2\\cos 18^{\\circ}$: $\\sin 18^{\\circ}\\cos 36^{\\circ} = \\dfrac{\\sin 36^{\\circ}\\cos 36^{\\circ}}{2\\cos 18^{\\circ}} = \\dfrac{\\sin 72^{\\circ}}{4\\cos 18^{\\circ}} = \\dfrac{1}{4}$, так как $\\sin 72^{\\circ} = \\cos 18^{\\circ}$.', 'd': [('Умножим и разделим на $2\\cos 18^{\\circ}$: $\\sin 18^{\\circ}\\cos 36^{\\circ} = \\dfrac{\\sin 36^{\\circ}\\cos 36^{\\circ}}{2\\cos 18^{\\circ}} = \\dfrac{\\sin 72^{\\circ}}{2\\cos 18^{\\circ}} = \\dfrac{1}{2}$, поэтому тождество неверно.', '$\\sin 36^{\\circ}\\cos 36^{\\circ} = \\dfrac{1}{2}\\sin 72^{\\circ}$: множитель $\\dfrac{1}{2}$ потерян.'), ('$\\sin 18^{\\circ}\\cos 36^{\\circ} = \\dfrac{1}{2}\\sin 54^{\\circ} = \\dfrac{1}{2}\\cos 36^{\\circ}$, а это не $\\dfrac{1}{4}$, поэтому тождество неверно.', 'Формула произведения: $\\sin 18^{\\circ}\\cos 36^{\\circ} = \\dfrac{1}{2}(\\sin 54^{\\circ} + \\sin(-18^{\\circ}))$; слагаемое $-\\sin 18^{\\circ}$ потеряно.'), ('$\\sin 18^{\\circ}\\cos 36^{\\circ} = \\sin 18^{\\circ} \\cdot \\cos(2 \\cdot 18^{\\circ}) = 2\\sin 18^{\\circ}\\cos 18^{\\circ} = \\sin 36^{\\circ} \\ne \\dfrac{1}{4}$, поэтому тождество неверно.', '$\\cos 36^{\\circ} = \\cos 2 \\cdot 18^{\\circ} = 1 - 2\\sin^{2} 18^{\\circ}$, а не $2\\cos 18^{\\circ}$.')]}, 'G10_TB_§23_23_35_2': {'k': 'Умножим на $\\sin\\dfrac{\\pi}{9} \\ne 0$ и трижды применим $2\\sin x\\cos x = \\sin 2x$: $8\\sin\\dfrac{\\pi}{9}\\cos\\dfrac{\\pi}{9}\\cos\\dfrac{2\\pi}{9}\\cos\\dfrac{4\\pi}{9} = \\sin\\dfrac{8\\pi}{9} = \\sin\\dfrac{\\pi}{9}$, поэтому произведение косинусов, умноженное на $8$, равно $1$.', 'd': [('$\\cos\\dfrac{\\pi}{9} = \\cos\\dfrac{2\\pi}{9} = \\cos\\dfrac{4\\pi}{9} = \\dfrac{1}{2}$, поэтому произведение равно $8 \\cdot \\dfrac{1}{8} = 1$.', '$\\dfrac{1}{2} = \\cos\\dfrac{\\pi}{3}$, а углы $\\dfrac{\\pi}{9}$, $\\dfrac{2\\pi}{9}$, $\\dfrac{4\\pi}{9}$ не равны $\\dfrac{\\pi}{3}$.'), ('Произведение косинусов равно косинусу суммы: $8\\cos\\left(\\dfrac{\\pi}{9} + \\dfrac{2\\pi}{9} + \\dfrac{4\\pi}{9}\\right) = 8\\cos\\dfrac{7\\pi}{9} \\ne 1$, поэтому тождество неверно.', 'Произведение косинусов не равно косинусу суммы углов.'), ('Умножим на $\\sin\\dfrac{\\pi}{9}$: $8\\sin\\dfrac{\\pi}{9}\\cos\\dfrac{\\pi}{9}\\cos\\dfrac{2\\pi}{9}\\cos\\dfrac{4\\pi}{9} = \\sin\\dfrac{8\\pi}{9} = -\\sin\\dfrac{\\pi}{9}$, поэтому выражение равно $-1$, поэтому тождество неверно.', '$\\sin\\dfrac{8\\pi}{9} = \\sin\\left(\\pi - \\dfrac{\\pi}{9}\\right) = \\sin\\dfrac{\\pi}{9}$: во второй четверти синус положителен.')]}, 'G10_TB_§23_23_35_3': {'k': '$\\sin 42^{\\circ} = \\cos 48^{\\circ}$; умножив $\\sin 6^{\\circ}\\cos 12^{\\circ}\\cos 24^{\\circ}\\cos 48^{\\circ}$ на $\\cos 6^{\\circ}$ и четырежды применив $\\sin x\\cos x = \\dfrac{1}{2}\\sin 2x$, получаем $\\dfrac{1}{16}\\sin 96^{\\circ} = \\dfrac{1}{16}\\cos 6^{\\circ}$, поэтому произведение равно $\\dfrac{1}{16}$.', 'd': [('$\\sin 42^{\\circ} = \\cos 48^{\\circ}$; после умножения на $\\cos 6^{\\circ}$ и применения формулы двойного угла получаем $\\dfrac{1}{8}\\sin 96^{\\circ}$, поэтому произведение равно $\\dfrac{1}{8}$, поэтому тождество неверно.', 'Формула применяется четыре раза, и каждый раз появляется множитель $\\dfrac{1}{2}$: $\\left(\\dfrac{1}{2}\\right)^{4} = \\dfrac{1}{16}$.'), ('$\\sin 6^{\\circ}\\sin 42^{\\circ} = \\dfrac{1}{2}(\\cos 36^{\\circ} + \\cos 48^{\\circ})$, $\\cos 12^{\\circ}\\cos 24^{\\circ} = \\dfrac{1}{2}(\\cos 12^{\\circ} + \\cos 36^{\\circ})$, и произведение не упрощается до числа, поэтому тождество неверно.', '$\\sin 6^{\\circ}\\sin 42^{\\circ} = \\dfrac{1}{2}(\\cos 36^{\\circ} - \\cos 48^{\\circ})$: в формуле произведения синусов стоит разность косинусов.'), ('$\\sin 42^{\\circ} = \\cos 42^{\\circ}$, поэтому после умножения на $\\cos 6^{\\circ}$ получается $\\dfrac{1}{16}\\sin 84^{\\circ}$, и произведение не равно $\\dfrac{1}{16}$, поэтому тождество неверно.', '$\\sin 42^{\\circ} = \\cos(90^{\\circ} - 42^{\\circ}) = \\cos 48^{\\circ}$.')]}, 'G10_TB_§23_23_36_1': {'k': '$\\sin 54^{\\circ}\\cos 72^{\\circ} = \\cos 36^{\\circ}\\sin 18^{\\circ}$; умножив и разделив на $2\\cos 18^{\\circ}$, получаем $\\dfrac{\\sin 36^{\\circ}\\cos 36^{\\circ}}{2\\cos 18^{\\circ}} = \\dfrac{\\sin 72^{\\circ}}{4\\cos 18^{\\circ}} = \\dfrac{1}{4}$.', 'd': [('$\\sin 54^{\\circ} = \\sin 36^{\\circ}$ и $\\cos 72^{\\circ} = \\cos 18^{\\circ}$, поэтому произведение равно $\\sin 36^{\\circ}\\cos 18^{\\circ} \\ne \\dfrac{1}{4}$, поэтому тождество неверно.', '$\\sin 54^{\\circ} = \\cos 36^{\\circ}$ и $\\cos 72^{\\circ} = \\sin 18^{\\circ}$: при переходе к дополнительному углу функция меняется на кофункцию.'), ('$\\sin 54^{\\circ}\\cos 72^{\\circ} = \\cos 36^{\\circ}\\sin 18^{\\circ} = \\dfrac{\\sin 72^{\\circ}}{2\\cos 18^{\\circ}} = \\dfrac{1}{2}$, поэтому тождество неверно.', '$\\sin 36^{\\circ}\\cos 36^{\\circ} = \\dfrac{1}{2}\\sin 72^{\\circ}$, поэтому получается $\\dfrac{\\sin 72^{\\circ}}{4\\cos 18^{\\circ}} = \\dfrac{1}{4}$.'), ('$\\sin 54^{\\circ}\\cos 72^{\\circ} = \\dfrac{1}{2}(\\sin 126^{\\circ} + \\sin 18^{\\circ})$, и это больше $\\dfrac{1}{2}\\sin 126^{\\circ} > \\dfrac{1}{4}$, поэтому тождество неверно.', '$\\sin\\alpha\\cos\\beta = \\dfrac{1}{2}(\\sin(\\alpha + \\beta) + \\sin(\\alpha - \\beta))$, а $\\sin(54^{\\circ} - 72^{\\circ}) = -\\sin 18^{\\circ}$.')]}, 'G10_TB_§23_23_36_2': {'k': 'Умножим на $\\sin 3\\alpha \\ne 0$ и трижды применим $2\\sin x\\cos x = \\sin 2x$: $8\\sin 3\\alpha\\cos 3\\alpha\\cos 6\\alpha\\cos 12\\alpha = \\sin 24\\alpha$, откуда $\\cos 3\\alpha\\cos 6\\alpha\\cos 12\\alpha = \\dfrac{\\sin 24\\alpha}{8\\sin 3\\alpha}$.', 'd': [('Умножим на $\\sin 3\\alpha$: $\\sin 3\\alpha\\cos 3\\alpha\\cos 6\\alpha\\cos 12\\alpha = \\sin 24\\alpha$, откуда левая часть равна $\\dfrac{\\sin 24\\alpha}{\\sin 3\\alpha}$, поэтому тождество неверно.', 'Каждое применение формулы даёт множитель $\\dfrac{1}{2}$: $\\sin x\\cos x = \\dfrac{1}{2}\\sin 2x$, всего $\\dfrac{1}{8}$.'), ('Умножим на $\\sin 3\\alpha$ и применим формулу двойного угла: $\\sin 3\\alpha\\cos 3\\alpha\\cos 6\\alpha\\cos 12\\alpha = \\dfrac{1}{8}\\sin 12\\alpha$, поэтому левая часть равна $\\dfrac{\\sin 12\\alpha}{8\\sin 3\\alpha}$, поэтому тождество неверно.', 'Углы удваиваются трижды: $3\\alpha \\to 6\\alpha \\to 12\\alpha \\to 24\\alpha$.'), ('Умножим на $\\cos 3\\alpha$: $\\cos^{2} 3\\alpha\\cos 6\\alpha\\cos 12\\alpha = \\dfrac{1}{8}\\sin 24\\alpha$, поэтому левая часть равна $\\dfrac{\\sin 24\\alpha}{8\\cos 3\\alpha}$, поэтому тождество неверно.', 'Формула двойного угла требует произведения $\\sin x\\cos x$; умножать нужно на $\\sin 3\\alpha$.')]}, 'G10_TB_§23_23_37': {'k': '$\\cos 2\\alpha = 2\\cos^{2}\\alpha - 1$, поэтому дробь равна $\\dfrac{2(1 + \\cos\\alpha)^{2}}{2(1 - \\cos\\alpha)^{2}} = \\dfrac{\\left(2\\cos^{2}\\frac{\\alpha}{2}\\right)^{2}}{\\left(2\\sin^{2}\\frac{\\alpha}{2}\\right)^{2}} = \\operatorname{ctg}^{4}\\dfrac{\\alpha}{2}$.', 'd': [('Дробь равна $\\dfrac{(1 + \\cos\\alpha)^{2}}{(1 - \\cos\\alpha)^{2}} = \\dfrac{\\left(2\\sin^{2}\\frac{\\alpha}{2}\\right)^{2}}{\\left(2\\cos^{2}\\frac{\\alpha}{2}\\right)^{2}} = \\operatorname{tg}^{4}\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$1 + \\cos\\alpha = 2\\cos^{2}\\dfrac{\\alpha}{2}$ и $1 - \\cos\\alpha = 2\\sin^{2}\\dfrac{\\alpha}{2}$: формулы перепутаны.'), ('Дробь равна $\\dfrac{1 + \\cos\\alpha}{1 - \\cos\\alpha} = \\operatorname{ctg}^{2}\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', 'Числитель и знаменатель — квадраты: $2(1 + \\cos\\alpha)^{2}$ и $2(1 - \\cos\\alpha)^{2}$.'), ('$\\cos 2\\alpha = 1 - 2\\cos^{2}\\alpha$, поэтому числитель равен $4 + 4\\cos\\alpha - 2\\cos^{2}\\alpha$, и дробь не равна $\\operatorname{ctg}^{4}\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$\\cos 2\\alpha = 2\\cos^{2}\\alpha - 1 = 1 - 2\\sin^{2}\\alpha$.')]}, 'G10_TB_§24_24_10_1': {'k': '$\\sin 5\\alpha + \\sin 8\\alpha = 2\\sin\\dfrac{13\\alpha}{2}\\cos\\dfrac{3\\alpha}{2}$, $\\sin 6\\alpha + \\sin 7\\alpha = 2\\sin\\dfrac{13\\alpha}{2}\\cos\\dfrac{\\alpha}{2}$, а $\\cos\\dfrac{3\\alpha}{2} + \\cos\\dfrac{\\alpha}{2} = 2\\cos\\alpha\\cos\\dfrac{\\alpha}{2}$, поэтому сумма равна $4\\cos\\dfrac{\\alpha}{2}\\cos\\alpha\\sin\\dfrac{13\\alpha}{2}$.', 'd': [('$\\sin 5\\alpha + \\sin 8\\alpha = 2\\cos\\dfrac{13\\alpha}{2}\\sin\\dfrac{3\\alpha}{2}$, $\\sin 6\\alpha + \\sin 7\\alpha = 2\\cos\\dfrac{13\\alpha}{2}\\sin\\dfrac{\\alpha}{2}$, поэтому сумма равна $4\\cos\\dfrac{13\\alpha}{2}\\sin\\alpha\\cos\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$\\sin x + \\sin y = 2\\sin\\dfrac{x + y}{2}\\cos\\dfrac{x - y}{2}$: синус и косинус перепутаны.'), ('Сумма равна $2\\sin\\dfrac{13\\alpha}{2}\\left(\\cos\\dfrac{3\\alpha}{2} + \\cos\\dfrac{\\alpha}{2}\\right) = 2\\sin\\dfrac{13\\alpha}{2}\\cos\\alpha\\cos\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$\\cos x + \\cos y = 2\\cos\\dfrac{x + y}{2}\\cos\\dfrac{x - y}{2}$: множитель $2$ потерян, и получается $4\\cos\\dfrac{\\alpha}{2}\\cos\\alpha\\sin\\dfrac{13\\alpha}{2}$.'), ('$\\sin 5\\alpha + \\sin 6\\alpha + \\sin 7\\alpha + \\sin 8\\alpha = \\sin 26\\alpha$, а это не равно правой части, поэтому тождество неверно.', 'Сумма синусов не равна синусу суммы углов.')]}, 'G10_TB_§24_24_11_1': {'k': '$1 + \\cos\\alpha + \\sin\\alpha = 2\\cos^{2}\\dfrac{\\alpha}{2} + 2\\sin\\dfrac{\\alpha}{2}\\cos\\dfrac{\\alpha}{2} = 2\\cos\\dfrac{\\alpha}{2}\\left(\\cos\\dfrac{\\alpha}{2} + \\sin\\dfrac{\\alpha}{2}\\right)$, а $\\cos\\dfrac{\\alpha}{2} + \\sin\\dfrac{\\alpha}{2} = \\sqrt{2}\\cos\\left(\\dfrac{\\alpha}{2} - \\dfrac{\\pi}{4}\\right)$.', 'd': [('$1 + \\cos\\alpha = 2\\sin^{2}\\dfrac{\\alpha}{2}$, поэтому левая часть равна $2\\sin\\dfrac{\\alpha}{2}\\left(\\sin\\dfrac{\\alpha}{2} + \\cos\\dfrac{\\alpha}{2}\\right) = 2\\sqrt{2}\\sin\\dfrac{\\alpha}{2}\\cos\\left(\\dfrac{\\alpha}{2} - \\dfrac{\\pi}{4}\\right)$, поэтому тождество неверно.', '$1 + \\cos\\alpha = 2\\cos^{2}\\dfrac{\\alpha}{2}$, а $2\\sin^{2}\\dfrac{\\alpha}{2} = 1 - \\cos\\alpha$.'), ('Левая часть равна $2\\cos\\dfrac{\\alpha}{2}\\left(\\cos\\dfrac{\\alpha}{2} + \\sin\\dfrac{\\alpha}{2}\\right)$, а $\\cos\\dfrac{\\alpha}{2} + \\sin\\dfrac{\\alpha}{2} = \\sqrt{2}\\cos\\left(\\dfrac{\\alpha}{2} + \\dfrac{\\pi}{4}\\right)$, поэтому тождество неверно.', '$\\sqrt{2}\\cos\\left(x + \\dfrac{\\pi}{4}\\right) = \\cos x - \\sin x$; сумме $\\cos x + \\sin x$ соответствует $\\sqrt{2}\\cos\\left(x - \\dfrac{\\pi}{4}\\right)$.'), ('Левая часть равна $2\\cos\\dfrac{\\alpha}{2}\\left(\\cos\\dfrac{\\alpha}{2} + \\sin\\dfrac{\\alpha}{2}\\right)$, а $\\cos\\dfrac{\\alpha}{2} + \\sin\\dfrac{\\alpha}{2} = \\cos\\left(\\dfrac{\\alpha}{2} - \\dfrac{\\pi}{4}\\right)$, поэтому она равна $2\\cos\\dfrac{\\alpha}{2}\\cos\\left(\\dfrac{\\alpha}{2} - \\dfrac{\\pi}{4}\\right)$, поэтому тождество неверно.', '$\\cos\\left(x - \\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}(\\cos x + \\sin x)$: потерян множитель $\\sqrt{2}$.')]}, 'G10_TB_§24_24_11_2': {'k': 'По формулам приведения дробь равна $\\dfrac{1 + \\cos 4\\alpha + \\sin 4\\alpha}{1 - \\cos 4\\alpha + \\sin 4\\alpha} = \\dfrac{2\\cos 2\\alpha(\\cos 2\\alpha + \\sin 2\\alpha)}{2\\sin 2\\alpha(\\sin 2\\alpha + \\cos 2\\alpha)} = \\operatorname{ctg} 2\\alpha$.', 'd': [('$\\cos\\left(4\\alpha + \\dfrac{3\\pi}{2}\\right) = -\\sin 4\\alpha$, поэтому знаменатель $1 - \\cos 4\\alpha - \\sin 4\\alpha$, и дробь не равна $\\operatorname{ctg} 2\\alpha$, поэтому тождество неверно.', '$\\cos\\left(\\dfrac{3\\pi}{2} + x\\right) = \\sin x$: в четвёртой четверти косинус положителен.'), ('Дробь равна $\\dfrac{2\\sin 2\\alpha(\\sin 2\\alpha + \\cos 2\\alpha)}{2\\cos 2\\alpha(\\cos 2\\alpha + \\sin 2\\alpha)} = \\operatorname{tg} 2\\alpha$, поэтому тождество неверно.', '$1 + \\cos 4\\alpha = 2\\cos^{2} 2\\alpha$ и $1 - \\cos 4\\alpha = 2\\sin^{2} 2\\alpha$: числитель и знаменатель перепутаны.'), ('$\\cos(4\\alpha - 2\\pi) = -\\cos 4\\alpha$ и $\\cos(4\\alpha + \\pi) = \\cos 4\\alpha$, поэтому дробь равна $\\dfrac{1 - \\cos 4\\alpha + \\sin 4\\alpha}{1 + \\cos 4\\alpha + \\sin 4\\alpha} = \\operatorname{tg} 2\\alpha$, поэтому тождество неверно.', '$2\\pi$ — период косинуса, поэтому $\\cos(4\\alpha - 2\\pi) = \\cos 4\\alpha$, а $\\cos(4\\alpha + \\pi) = -\\cos 4\\alpha$.')]}, 'G10_TB_§24_24_11_3': {'k': 'При $A = \\dfrac{15\\pi}{8} - 2\\alpha$, $B = \\dfrac{17\\pi}{8} - 2\\alpha$ по формулам понижения степени $\\sin^{2} A - \\cos^{2} B = -\\dfrac{\\cos 2A + \\cos 2B}{2} = -\\cos(A + B)\\cos(A - B)$, где $A + B = 4\\pi - 4\\alpha$, $A - B = -\\dfrac{\\pi}{4}$, поэтому левая часть равна $-\\cos 4\\alpha \\cdot \\dfrac{\\sqrt{2}}{2} = -\\dfrac{\\cos 4\\alpha}{\\sqrt{2}}$.', 'd': [('$\\sin^{2} A - \\cos^{2} B = \\dfrac{\\cos 2A + \\cos 2B}{2} = \\cos(A + B)\\cos(A - B) = \\dfrac{\\cos 4\\alpha}{\\sqrt{2}}$, поэтому тождество неверно.', '$\\sin^{2} A = \\dfrac{1 - \\cos 2A}{2}$ и $\\cos^{2} B = \\dfrac{1 + \\cos 2B}{2}$, поэтому разность равна $-\\dfrac{\\cos 2A + \\cos 2B}{2}$.'), ('$\\sin^{2} A - \\cos^{2} B = -\\cos(A + B)\\cos(A - B)$, где $A + B = 4\\pi - 4\\alpha$, $A - B = -\\dfrac{\\pi}{4}$, поэтому левая часть равна $-\\cos 4\\alpha$, поэтому тождество неверно.', '$\\cos\\left(-\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$: этот множитель потерян.'), ('$\\sin^{2} A - \\cos^{2} B = -\\cos(A + B)\\cos(A - B)$, где $A + B = 4\\pi - 4\\alpha$, а $\\cos(4\\pi - 4\\alpha) = \\sin 4\\alpha$, поэтому левая часть равна $-\\dfrac{\\sin 4\\alpha}{\\sqrt{2}}$, поэтому тождество неверно.', '$4\\pi$ — период косинуса, и косинус чётен: $\\cos(4\\pi - 4\\alpha) = \\cos 4\\alpha$.')]}, 'G10_TB_§24_24_12_1': {'k': '$1 - 2\\cos\\alpha + \\cos 2\\alpha = 2\\cos^{2}\\alpha - 2\\cos\\alpha = 2\\cos\\alpha(\\cos\\alpha - 1)$, а $\\cos\\alpha - 1 = -2\\sin^{2}\\dfrac{\\alpha}{2}$, поэтому левая часть равна $-4\\cos\\alpha\\sin^{2}\\dfrac{\\alpha}{2}$.', 'd': [('$\\cos 2\\alpha = 1 - 2\\cos^{2}\\alpha$, поэтому левая часть равна $2 - 2\\cos\\alpha - 2\\cos^{2}\\alpha$, и она не равна правой части, поэтому тождество неверно.', '$\\cos 2\\alpha = 2\\cos^{2}\\alpha - 1$; формула $1 - 2\\sin^{2}\\alpha$ содержит синус, а не косинус.'), ('Левая часть равна $2\\cos\\alpha(\\cos\\alpha - 1)$, а $\\cos\\alpha - 1 = 2\\sin^{2}\\dfrac{\\alpha}{2}$, поэтому она равна $4\\cos\\alpha\\sin^{2}\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$1 - \\cos\\alpha = 2\\sin^{2}\\dfrac{\\alpha}{2}$, поэтому $\\cos\\alpha - 1 = -2\\sin^{2}\\dfrac{\\alpha}{2}$: знак потерян.'), ('Левая часть равна $2\\cos\\alpha(\\cos\\alpha - 1)$, а $\\cos\\alpha - 1 = -2\\cos^{2}\\dfrac{\\alpha}{2}$, поэтому она равна $-4\\cos\\alpha\\cos^{2}\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$1 - \\cos\\alpha = 2\\sin^{2}\\dfrac{\\alpha}{2}$; через $\\cos^{2}\\dfrac{\\alpha}{2}$ выражается $1 + \\cos\\alpha$.')]}, 'G10_TB_§24_24_12_2': {'k': '$1 - \\sin\\alpha - \\cos\\alpha = \\sqrt{2}(\\sin 45^{\\circ} - \\sin(\\alpha + 45^{\\circ})) = -2\\sqrt{2}\\sin\\dfrac{\\alpha}{2}\\cos\\left(\\dfrac{\\alpha}{2} + 45^{\\circ}\\right)$, а $\\cos\\left(\\dfrac{\\alpha}{2} + 45^{\\circ}\\right) = -\\sin\\left(\\dfrac{\\alpha}{2} - 45^{\\circ}\\right)$, поэтому левая часть равна $2\\sqrt{2}\\sin\\dfrac{\\alpha}{2}\\sin\\left(\\dfrac{\\alpha}{2} - 45^{\\circ}\\right)$.', 'd': [('$\\sin 45^{\\circ} - \\sin(\\alpha + 45^{\\circ}) = -2\\sin\\dfrac{\\alpha}{2}\\cos\\left(\\dfrac{\\alpha}{2} + 45^{\\circ}\\right)$ и $\\cos\\left(\\dfrac{\\alpha}{2} + 45^{\\circ}\\right) = \\sin\\left(\\dfrac{\\alpha}{2} - 45^{\\circ}\\right)$, поэтому левая часть равна $-2\\sqrt{2}\\sin\\dfrac{\\alpha}{2}\\sin\\left(\\dfrac{\\alpha}{2} - 45^{\\circ}\\right)$, поэтому тождество неверно.', '$\\cos\\left(x + 45^{\\circ}\\right) = \\sin\\left(45^{\\circ} - x\\right) = -\\sin\\left(x - 45^{\\circ}\\right)$: знак потерян.'), ('$\\sin\\alpha + \\cos\\alpha = \\sqrt{2}\\cos(\\alpha + 45^{\\circ})$, поэтому левая часть равна $\\sqrt{2}(\\cos 45^{\\circ} - \\cos(\\alpha + 45^{\\circ})) = 2\\sqrt{2}\\sin\\dfrac{\\alpha}{2}\\sin\\left(\\dfrac{\\alpha}{2} + 45^{\\circ}\\right)$, поэтому тождество неверно.', '$\\sin\\alpha + \\cos\\alpha = \\sqrt{2}\\sin(\\alpha + 45^{\\circ}) = \\sqrt{2}\\cos(\\alpha - 45^{\\circ})$, а не $\\sqrt{2}\\cos(\\alpha + 45^{\\circ})$.'), ('$1 - \\sin\\alpha - \\cos\\alpha = 1 - \\sin\\alpha - \\cos\\alpha$, и при $\\alpha = 0$ обе части равны $0$, поэтому тождество верно.', 'Проверка в одной точке не доказывает тождества.')]}, 'G10_TB_§24_24_12_3': {'k': '$\\cos^{2} A - \\cos^{2} B = (\\cos A - \\cos B)(\\cos A + \\cos B) = \\left(-2\\sin\\dfrac{5\\pi}{4}\\sin(-2\\alpha)\\right)\\left(2\\cos\\dfrac{5\\pi}{4}\\cos 2\\alpha\\right) = (-\\sqrt{2}\\sin 2\\alpha)(-\\sqrt{2}\\cos 2\\alpha) = \\sin 4\\alpha$, где $A = \\dfrac{5\\pi}{4} - 2\\alpha$, $B = \\dfrac{5\\pi}{4} + 2\\alpha$.', 'd': [('$(\\cos A - \\cos B)(\\cos A + \\cos B) = (\\sqrt{2}\\sin 2\\alpha)(-\\sqrt{2}\\cos 2\\alpha) = -\\sin 4\\alpha$, поэтому тождество неверно.', '$\\cos A - \\cos B = -2\\sin\\dfrac{A + B}{2}\\sin\\dfrac{A - B}{2}$ с $\\sin\\dfrac{5\\pi}{4} = -\\dfrac{\\sqrt{2}}{2}$ и $\\sin(-2\\alpha) = -\\sin 2\\alpha$ даёт $-\\sqrt{2}\\sin 2\\alpha$.'), ('$\\cos^{2} A - \\cos^{2} B = \\cos(A^{2} - B^{2})$, а $A^{2} - B^{2} = -10\\pi\\alpha$, поэтому левая часть не равна $\\sin 4\\alpha$, поэтому тождество неверно.', 'Разность квадратов косинусов не равна косинусу разности квадратов углов.'), ('$\\cos^{2} A - \\cos^{2} B = (\\cos A - \\cos B)(\\cos A + \\cos B) = \\sin 2\\alpha \\cdot \\cos 2\\alpha = \\sin 2\\alpha\\cos 2\\alpha$, т. е. левая часть равна $\\dfrac{1}{2}\\sin 4\\alpha$, поэтому тождество неверно.', 'Множители равны $-\\sqrt{2}\\sin 2\\alpha$ и $-\\sqrt{2}\\cos 2\\alpha$; коэффициенты $\\sqrt{2}$ потеряны, а $2\\sin 2\\alpha\\cos 2\\alpha = \\sin 4\\alpha$.')]}, 'G10_TB_§24_24_9_1': {'k': '$\\cos 3\\alpha - \\cos 5\\alpha = 2\\sin 4\\alpha\\sin\\alpha$, $\\cos 6\\alpha - \\cos 4\\alpha = -2\\sin 5\\alpha\\sin\\alpha$, поэтому левая часть равна $2\\sin\\alpha(\\sin 4\\alpha - \\sin 5\\alpha) = 2\\sin\\alpha \\cdot \\left(-2\\cos\\dfrac{9\\alpha}{2}\\sin\\dfrac{\\alpha}{2}\\right) = -4\\sin\\dfrac{\\alpha}{2}\\sin\\alpha\\cos\\dfrac{9\\alpha}{2}$.', 'd': [('$\\cos 3\\alpha - \\cos 5\\alpha = 2\\sin 4\\alpha\\sin\\alpha$, $\\cos 6\\alpha - \\cos 4\\alpha = 2\\sin 5\\alpha\\sin\\alpha$, поэтому левая часть равна $4\\sin\\alpha\\sin\\dfrac{9\\alpha}{2}\\cos\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$\\cos 6\\alpha - \\cos 4\\alpha = -2\\sin 5\\alpha\\sin\\alpha$: при вычитании большего угла из меньшего знак другой.'), ('Левая часть равна $2\\sin\\alpha(\\sin 4\\alpha - \\sin 5\\alpha)$, а $\\sin 4\\alpha - \\sin 5\\alpha = -2\\sin\\dfrac{9\\alpha}{2}\\cos\\dfrac{\\alpha}{2}$, поэтому она равна $-4\\sin\\alpha\\sin\\dfrac{9\\alpha}{2}\\cos\\dfrac{\\alpha}{2}$, поэтому тождество неверно.', '$\\sin x - \\sin y = 2\\sin\\dfrac{x - y}{2}\\cos\\dfrac{x + y}{2}$: синус берётся от полуразности, косинус — от полусуммы.'), ('$\\cos 3\\alpha - \\cos 4\\alpha - \\cos 5\\alpha + \\cos 6\\alpha = \\cos(3\\alpha - 4\\alpha - 5\\alpha + 6\\alpha) = \\cos 0 = 1$, поэтому тождество неверно.', 'Сумма косинусов не равна косинусу суммы углов.')]}, 'G10_TB_§24_24_9_2': {'k': 'По формулам приведения левая часть равна $\\sin 4\\alpha + \\sin 8\\alpha + \\sin 12\\alpha$; $\\sin 4\\alpha + \\sin 8\\alpha = 2\\sin 6\\alpha\\cos 2\\alpha$ и $\\sin 12\\alpha = 2\\sin 6\\alpha\\cos 6\\alpha$, поэтому она равна $2\\sin 6\\alpha(\\cos 2\\alpha + \\cos 6\\alpha) = 4\\cos 2\\alpha\\cos 4\\alpha\\sin 6\\alpha$.', 'd': [('По формулам приведения левая часть равна $-\\sin 4\\alpha - \\sin 8\\alpha + \\sin 12\\alpha$, и она не равна правой части, поэтому тождество неверно.', '$\\cos\\left(\\dfrac{3\\pi}{2} + 4\\alpha\\right) = \\sin 4\\alpha$ и $\\sin(3\\pi - 8\\alpha) = \\sin 8\\alpha$: знаки определены неверно.'), ('Левая часть равна $\\sin 4\\alpha + \\sin 8\\alpha - \\sin 12\\alpha$, так как $\\sin(4\\pi - 12\\alpha) = \\sin 12\\alpha$, и она не равна правой части, поэтому тождество неверно.', '$\\sin(4\\pi - 12\\alpha) = -\\sin 12\\alpha$, поэтому $-\\sin(4\\pi - 12\\alpha) = \\sin 12\\alpha$.'), ('Левая часть равна $\\sin 4\\alpha + \\sin 8\\alpha + \\sin 12\\alpha = 2\\sin 6\\alpha\\cos 2\\alpha + 2\\sin 6\\alpha\\cos 6\\alpha = 2\\sin 6\\alpha(\\cos 2\\alpha + \\cos 6\\alpha) = 2\\sin 6\\alpha\\cos 4\\alpha\\cos 2\\alpha$, поэтому тождество неверно.', '$\\cos 2\\alpha + \\cos 6\\alpha = 2\\cos 4\\alpha\\cos 2\\alpha$: множитель $2$ потерян.')]}, 'G10_TB_§24_24_9_7': {'k': 'После раскрытия скобок левая часть равна $2 - 2(\\cos\\alpha\\cos\\beta + \\sin\\alpha\\sin\\beta) = 2 - 2\\cos(\\alpha - \\beta) = 4\\sin^{2}\\dfrac{\\alpha - \\beta}{2}$.', 'd': 'KEEP'}, 'G10_TB_§25_25_10': {'k': 'При $x = \\dfrac{\\alpha}{2}$ имеем $\\cos(30^{\\circ} - x) = \\sin(60^{\\circ} + x)$ и $\\sin(60^{\\circ} + x)\\sin(60^{\\circ} - x) = \\sin^{2} 60^{\\circ} - \\sin^{2} x = \\dfrac{3}{4} - \\sin^{2} x$, поэтому левая часть равна $4\\sin x\\left(\\dfrac{3}{4} - \\sin^{2} x\\right) = 3\\sin x - 4\\sin^{3} x = \\sin 3x = \\sin\\dfrac{3\\alpha}{2}$.', 'd': [('При $x = \\dfrac{\\alpha}{2}$: $\\sin(60^{\\circ} + x)\\sin(60^{\\circ} - x) = \\sin^{2} 60^{\\circ} + \\sin^{2} x$, поэтому левая часть равна $3\\sin x + 4\\sin^{3} x$, поэтому тождество неверно.', '$\\sin(a + b)\\sin(a - b) = \\sin^{2} a - \\sin^{2} b$.'), ('При $x = \\dfrac{\\alpha}{2}$ левая часть равна $3\\sin x - 4\\sin^{3} x = \\sin 3x = \\sin 3\\alpha$, поэтому тождество неверно.', '$3x = \\dfrac{3\\alpha}{2}$, а не $3\\alpha$.'), ('При $x = \\dfrac{\\alpha}{2}$: $\\cos(30^{\\circ} - x) = \\cos(60^{\\circ} + x)$, поэтому левая часть равна $4\\sin x\\cos(60^{\\circ} + x)\\sin(60^{\\circ} - x)$, и она не сводится к $\\sin 3x$, поэтому тождество неверно.', '$\\cos(30^{\\circ} - x) = \\sin(90^{\\circ} - 30^{\\circ} + x) = \\sin(60^{\\circ} + x)$.')]}, 'G10_TB_§25_25_11_1': {'k': 'Умножим сумму $S$ на $2\\sin\\dfrac{\\pi}{7}$: по формуле $2\\sin x\\cos y = \\sin(x + y) - \\sin(y - x)$ получаем $\\left(\\sin\\dfrac{3\\pi}{7} - \\sin\\dfrac{\\pi}{7}\\right) + \\left(\\sin\\dfrac{5\\pi}{7} - \\sin\\dfrac{3\\pi}{7}\\right) + \\left(\\sin\\pi - \\sin\\dfrac{5\\pi}{7}\\right) = -\\sin\\dfrac{\\pi}{7}$, поэтому $S = -\\dfrac{1}{2}$.', 'd': [('Умножим сумму на $2\\sin\\dfrac{\\pi}{7}$: получаем $\\sin\\pi - \\sin\\dfrac{\\pi}{7} = -\\sin\\dfrac{\\pi}{7}$, поэтому сумма равна $-1$, поэтому тождество неверно.', 'Сумма умножалась на $2\\sin\\dfrac{\\pi}{7}$, поэтому $S = \\dfrac{-\\sin\\frac{\\pi}{7}}{2\\sin\\frac{\\pi}{7}} = -\\dfrac{1}{2}$.'), ('$\\cos\\dfrac{2\\pi}{7} + \\cos\\dfrac{4\\pi}{7} + \\cos\\dfrac{6\\pi}{7} = \\cos\\dfrac{12\\pi}{7} = \\cos\\dfrac{2\\pi}{7} > 0$, поэтому тождество неверно.', 'Сумма косинусов не равна косинусу суммы углов.'), ('$\\cos\\dfrac{6\\pi}{7} = -\\cos\\dfrac{2\\pi}{7}$, поэтому сумма равна $\\cos\\dfrac{4\\pi}{7} \\ne -\\dfrac{1}{2}$, поэтому тождество неверно.', '$\\cos\\dfrac{6\\pi}{7} = -\\cos\\dfrac{\\pi}{7}$, так как $\\dfrac{6\\pi}{7} = \\pi - \\dfrac{\\pi}{7}$.')]}}
